var locales3 = { en: en3, zh: zh3 };

// src/client/machines/index.tsx
function registerMachines(ctx, api, readers) {
  ctx.effect(() => ctx.locale.register(NS3, locales3), "dsh-layerfs: machines locale");
  const t = ctx.locale.bind(NS3);
  const shown = () => readers.includes(ctx.layout?.panelInfo?.getSnapshot?.().activePanelId);
  const controller = new MachinesController(api, shown);
  ctx.effect(() => () => controller.dispose(), "dsh-layerfs: machines controller");
  ctx.effect(() => {
    let was = shown();
    return ctx.layout?.panelInfo?.subscribe?.(() => {
      const now = shown();
      if (now && !was) controller.reload();
      was = now;
    }) ?? (() => {
    });
  }, "dsh-layerfs: machines panel focus");
  return { face: controller.face(), t };
}

